class Solution {
public:
    int maximizeTheProfit(int n, vector<vector<int>>& offers) {
        vector<vector<pair<int, int>>> by_end(n);
        for (auto& o : offers) {
            by_end[o[1]].push_back({o[0], o[2]});
        }
        vector<int> dp(n, 0);
        for (int i = 0; i < n; ++i) {
            dp[i] = i > 0 ? dp[i - 1] : 0;
            for (auto& [start, gold] : by_end[i]) {
                int prev = start > 0 ? dp[start - 1] : 0;
                dp[i] = max(dp[i], prev + gold);
            }
        }
        return dp[n - 1];
    }
};

import java.util.*;

class Solution {
    public int maximizeTheProfit(int n, List<List<Integer>> offers) {
        List<List<int[]>> byEnd = new ArrayList<>();
        for (int i = 0; i < n; i++) byEnd.add(new ArrayList<>());
        for (List<Integer> o : offers) {
            byEnd.get(o.get(1)).add(new int[]{o.get(0), o.get(2)});
        }
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) {
            dp[i] = i > 0 ? dp[i - 1] : 0;
            for (int[] pair : byEnd.get(i)) {
                int start = pair[0], gold = pair[1];
                int prev = start > 0 ? dp[start - 1] : 0;
                dp[i] = Math.max(dp[i], prev + gold);
            }
        }
        return dp[n - 1];
    }
}

