var maximizeTheProfit = function(n, offers) {
    const byEnd = Array.from({ length: n }, () => []);
    for (const [start, end, gold] of offers) {
        byEnd[end].push([start, gold]);
    }
    const dp = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        dp[i] = i > 0 ? dp[i - 1] : 0;
        for (const [start, gold] of byEnd[i]) {
            const prev = start > 0 ? dp[start - 1] : 0;
            if (prev + gold > dp[i]) dp[i] = prev + gold;
        }
    }
    return dp[n - 1];
};
